<?php
require dirname(__DIR__).'/bootstrap.php';header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store, private');
try{requireAdmin();ensureCikokoAdvancedSchema();require_once dirname(__DIR__).'/api/mobile/tracking_v9.php';ensureTrackingV9();$rows=db()->query("SELECT s.*,u.nama_lengkap,u.nomor_pegawai,u.role,q.fix_epoch,q.received_at gps_received_at FROM tracking_sessions s JOIN users u ON u.id=s.user_id LEFT JOIN tracking_live_quality q ON q.session_id=s.id WHERE s.status='active' ORDER BY s.last_seen_at DESC")->fetchAll();$out=array();foreach($rows as $r){$fix=!empty($r['fix_epoch'])?(int)$r['fix_epoch']:strtotime((string)$r['last_seen_at']);$age=max(0,time()-$fix);$r['fix_time_verified']=!empty($r['fix_epoch']);$r['gps_age_seconds']=$age;$r['gps_fix_at']=date('Y-m-d H:i:s',$fix);$r['freshness']=$r['fix_time_verified']?($age<=15?'live':($age<=90?'stale':'offline')):'offline';$r['quality_label']=!isset($r['last_accuracy'])||(float)$r['last_accuracy']<=0?'Tidak diketahui':((float)$r['last_accuracy']<=20?'Baik':((float)$r['last_accuracy']<=30?'Sedang':'Rendah'));$r['role_label']=roleLabel((string)($r['role']??''));$out[]=$r;}echo json_encode(array('ok'=>true,'rows'=>$out,'poll_interval_seconds'=>5,'server_epoch'=>time(),'server_time'=>date('Y-m-d H:i:s')));}catch(Throwable $e){http_response_code(500);echo json_encode(array('ok'=>false,'message'=>userError($e)));}
